// Package periods turns a cumulative double-entry book into a period report:
// per-account movement over a date window, the period income statement, and
// the closing entry that sweeps nominal accounts into equity.
//
// [p/journal] is cumulative by construction and says so. Its Close is a
// backdating seal — it refuses entries dated at or before a cutoff and does
// not sweep anything — so revenue and expense accumulate from the book's first
// posting forever, and [p/statements] names its three figures
// CumulativeRevenue, CumulativeExpenses and CumulativeNet for that reason. Its
// package doc states the gap in one sentence: "A period income statement needs
// entry-level data and is out of scope." This package is that entry-level
// consumer. It reads no chain, holds no state, and writes nothing.
//
//	w := Window{From: q1Start, Until: q2Start}
//	rep, err := Derive(chart, entries, w)
//	// rep.Activity, rep.PeriodNet, rep.CrossWindowReversals
//	post, err := rep.ClosingEntry("3100")   // a PROPOSAL, not a write
//
// # Why the chart is a parameter
//
// [journal.Posting] is {Account string, Side, Amount int64}: it carries the
// account's CODE and never its Kind. So revenue cannot be told from expense
// from postings alone, and no income statement is derivable without the chart.
// That single fact fixes this package's signature. Only Code, Name and Kind
// are read; Debits and Credits are the book's CUMULATIVE columns and are
// deliberately neither read nor validated here, because period movement comes
// from the entries.
//
// # The window is closed-open
//
// [Window] is [From, Until): From is included, Until is not. Consecutive
// periods therefore TILE — [Window.Tiles] is the predicate — with no overlap
// and no gap, which is what makes a sequence of period reports add up to the
// cumulative figures. A closed-closed window double-counts exactly one
// timestamp per boundary, and that error is invisible in any single report.
//
// # Two inputs, two ordering decisions, opposite answers
//
// This package imposes an ordering precondition on one input and refuses one
// on the other, and the rule separating them is what journal GUARANTEES:
//
//   - chart must be strictly ascending by Code ([ErrChartNotOrdered]).
//     [journal.Book.IterateAccounts] is "ascending code order", so every
//     producer meets it. It buys duplicate-code detection, chart-order output
//     with no sort, and a binary-search code lookup instead of a map.
//   - entries must be strictly ascending by ID ([ErrEntriesNotOrdered]).
//     [journal.Book.IterateEntries] and [journal.Book.Entries] both guarantee
//     it. It buys duplicate-ID detection, the binary search that resolves
//     ReversalOf, and ID >= 1 for free, 0 being ReversalOf's sentinel.
//   - entries must NOT be required in ascending At order, and this package
//     must never require it. At is caller-supplied and backdating is legal
//     until Close seals it, so journal guarantees nothing about it. Such a
//     precondition would be one no producer in this portfolio can meet — a
//     gate that can never pass, in an API signature rather than in a checker.
//
// # The reversal census has three buckets, and the third is the point
//
// A reversal dated inside the window whose original is dated outside it
// changes what the period means: the window carries a correction to activity
// it never contained. The census reports three things and never two:
//
//   - [Report.Reversals] — in-window reversal, original also in-window:
//     ordinary, classified.
//   - [Report.CrossWindowReversals] — in-window reversal, original dated
//     outside: classified, and material.
//   - [Report.UnresolvedReversals] — in-window reversal whose original is
//     ABSENT from the entries slice, so the classification COULD NOT BE MADE.
//
// Collapsing the third into either of the first two would read "could not
// evaluate" as assent. It is a census, not a verdict — the same posture as
// [statements.Statement.Abnormal] — and it is a function of what the caller
// passed, not of the book: pass a window-filtered slice and every reversal
// reaching back before it is unresolved by construction.
//
// # What this package does not do
//
//   - **It never writes.** [Report.ClosingEntry] returns postings for the
//     caller to Post. It sweeps PERIOD MOVEMENT, not cumulative balance, so
//     running it twice over one window and posting both results
//     double-sweeps — and this package never sees the Book, so it cannot
//     detect that. The caller owns idempotence.
//   - **No paging, no Merge.** [MaxEntries] is the hard bound. Merging reports
//     across pages would make UnresolvedReversals an artifact of the paging
//     rather than of the data; fixing that needs a two-pass design over the
//     whole entry set and is a different package.
//   - **No cash-flow statement.** The indirect method needs a
//     cash-vs-accrual classification [journal.Posting] does not carry.
//     [Report.Activity] is the balance-sheet delta half it would need.
//   - **No audit.** Every figure is derived from what the caller supplied. A
//     chart from one book and entries from another produce a plausible report
//     and nothing here detects it.
//
// [p/journal]: /p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/journal
// [p/statements]: /p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/statements
package periods

import (
	"errors"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/journal"
	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/statements"
)

// MaxAccounts bounds the chart [Derive] will accept. It is
// [statements.MaxRows] — journal's own account cap, reached through the
// package that already made this decision rather than restated — because a
// row set larger than the largest chart this ecosystem's bookkeeping
// primitive can hold did not come from a chart.
const MaxAccounts = statements.MaxRows

// MaxEntries bounds the entry slice [Derive] will walk, and it is set far
// below [journal.MaxEntriesLimit] on purpose: the journal holds a million
// entries and a million-entry loop is not a transaction.
//
// What the bound costs, stated rather than waved at. Derive makes one pass
// over the entries and, per entry, one pass over its postings, each posting
// costing a binary search over the chart. [journal.MaxPostingsPerEntry] is 64
// and is re-checked here ([ErrTooManyPostings]) so the product is a PROVEN
// ceiling and not an assumed one:
//
//	4096 entries x 64 postings = 262 144 posting visits, each a
//	log2(10 000) ~ 14-step search
//
// which is the same order as the 10 000-row walk [statements.Derive]
// documents. A realm wanting period reports caps its own journal at or below
// this; r/books allows 128 accounts and should be read the same way — this is
// the ceiling a caller may ask for, not a size worth reaching.
const MaxEntries = 4096

// Errors returned by this package.
var (
	// ErrInvalidWindow is a window failing [Window.Valid]: From negative, or
	// Until not strictly after From. An empty window is refused rather than
	// reported as a period with no activity, because the two are different
	// claims and only one of them is a report.
	ErrInvalidWindow = errors.New("periods: window must satisfy 0 <= From < Until")

	// ErrTooManyAccounts is a chart longer than [MaxAccounts].
	ErrTooManyAccounts = errors.New("periods: chart length exceeds MaxAccounts")

	// ErrTooManyEntries is an entry slice longer than [MaxEntries].
	ErrTooManyEntries = errors.New("periods: entry count exceeds MaxEntries")

	// ErrChartNotOrdered is a chart not in strictly ascending Code order.
	// journal's own enumerator is, so this also catches a duplicated code.
	ErrChartNotOrdered = errors.New("periods: chart must be in strictly ascending code order")

	// ErrEntriesNotOrdered is an entry slice not in strictly ascending ID
	// order, which includes an ID of zero. Both of journal's producers are
	// ordered; see the package doc on why At carries no such requirement.
	ErrEntriesNotOrdered = errors.New("periods: entries must be in strictly ascending ID order")

	// ErrInvalidKind is an account whose Kind is outside journal's five. The
	// zero Kind is the case that matters: journal reports it as
	// credit-normal, so a silent fallthrough would file it rather than refuse
	// it.
	//
	// The two producers are not symmetrical, and saying so is the point.
	// [Derive] raises it from the CHART PRE-PASS, which proves every Kind
	// [journal.Kind.Valid] before anything is summed; its later
	// [statements.SectionOf] branch is therefore UNREACHABLE, because
	// SectionOf's switch covers exactly the five kinds Valid admits. That
	// branch ships anyway, as fail-closed defence against the two definitions
	// drifting apart in a later version of either package — but it is not a
	// path this package can reach today and must not be cited as one.
	// [Report.ClosingEntry] is the reachable SectionOf case: it is handed a
	// Report rather than a chart, runs no pre-pass, and so a hand-built row
	// with an invalid Kind reaches SectionOf directly.
	ErrInvalidKind = errors.New("periods: unknown account kind")

	// ErrInvalidPosting is a posting with an invalid Side or a non-positive
	// Amount. journal cannot produce one; a hand-built entry can.
	ErrInvalidPosting = errors.New("periods: posting needs a valid side and a positive amount")

	// ErrTooManyPostings is an entry with more than
	// [journal.MaxPostingsPerEntry] postings. journal cannot produce one, and
	// re-checking is what makes [MaxEntries]'s cost bound a proven ceiling.
	ErrTooManyPostings = errors.New("periods: entry exceeds journal.MaxPostingsPerEntry")

	// ErrUnknownAccount is a posting naming a code absent from the chart.
	// Dropping it silently would UNDERSTATE the period, which is worse than
	// refusing to report it.
	ErrUnknownAccount = errors.New("periods: posting names a code absent from the chart")

	// ErrNegativeColumns is an [Activity] row whose Debits or Credits is
	// negative. [Derive] cannot produce one — it accumulates positive posting
	// amounts from zero — so this is only reachable through a hand-built
	// Report, and it is checked for the reason [statements.ErrNegativeTotals]
	// is checked over the identical hazard on the identical type.
	//
	// [Activity.Movement] delegates to [journal.Account.Balance], which
	// subtracts one column from the other with no check of its own. A row
	// carrying Credits near max and a NEGATIVE Debits therefore yields a
	// WRAPPED movement before any arithmetic here runs, and the wrap survives
	// every downstream guard: it is nonzero, so the m == 0 skip does not
	// fire, and it is not minInt64, so magnitude reports success. The result
	// was a closing posting with an INVERTED SIGN, balanced, both sides
	// present, within the posting cap, and acceptable to [journal.Book.Post]
	// — a wrong figure with no error anywhere, which is strictly worse than
	// [ErrOverflow] because nothing downstream can tell it from a real one.
	// With both columns non-negative the subtraction lands in
	// [-maxInt64, maxInt64] and cannot wrap, which is the precondition the
	// checked arithmetic in [Report.ClosingEntry] is sufficient under.
	ErrNegativeColumns = errors.New("periods: activity column totals must not be negative")

	// ErrInvalidEquityCode is an empty equity code, or one longer than
	// [journal.MaxCodeLen].
	ErrInvalidEquityCode = errors.New("periods: equity code must be non-empty and within journal.MaxCodeLen")

	// ErrEquityCodeIsNominal is an equity code naming one of the nominal
	// accounts being swept. The resulting entry would balance and mean
	// nothing. See [Report.ClosingEntry] on what this check cannot cover.
	ErrEquityCodeIsNominal = errors.New("periods: equity code names a nominal account being closed")

	// ErrNothingToClose is a window with no nominal movement at all. The
	// alternative is returning an empty posting slice that journal would
	// refuse with ErrTooFewPostings, which moves the failure one call later
	// where it is harder to read.
	ErrNothingToClose = errors.New("periods: no nominal movement in the window")

	// ErrTooManyNominalAccounts is a sweep that would exceed
	// [journal.MaxPostingsPerEntry]: at most 63 nominal accounts plus the
	// equity posting.
	ErrTooManyNominalAccounts = errors.New("periods: closing entry exceeds journal.MaxPostingsPerEntry")

	// ErrOverflow is an int64 overflow in any accumulation.
	ErrOverflow = errors.New("periods: int64 overflow")
)

// Window is a half-open date range [From, Until): From is included, Until is
// not. The unit is whatever the book's At values are — journal treats At as an
// opaque non-negative int64, so a caller holding seconds passes seconds and a
// caller holding block heights passes heights. This package imposes no
// calendar, which is why it needs none.
type Window struct {
	From  int64
	Until int64
}

// Valid reports whether w is a usable window: From non-negative and Until
// strictly after it. An empty or inverted window is not a period.
func (w Window) Valid() bool { return w.From >= 0 && w.From < w.Until }

// Contains reports whether at falls in w. Half-open: From is in, Until is out.
func (w Window) Contains(at int64) bool { return at >= w.From && at < w.Until }

// Tiles reports whether next begins exactly where w ends, so that the two
// cover [w.From, next.Until) with no overlap and no gap.
//
// It exists as API rather than as a comment because the tiling property is
// what makes a sequence of period reports sum to the cumulative figures, and a
// caller generating a sequence should be able to assert it.
func (w Window) Tiles(next Window) bool {
	return w.Valid() && next.Valid() && w.Until == next.From
}

// Activity is one account's movement WITHIN the window. Debits and Credits are
// period sums, not the book's cumulative columns, and both are non-negative AS
// PRODUCED BY [Derive] — postings carry positive amounts and Derive refuses
// anything else.
//
// A Report assembled by hand is under no such constraint, so
// [Report.ClosingEntry] checks it: a negative column there is
// [ErrNegativeColumns]. The check is not tidiness. [Movement] delegates to
// [journal.Account.Balance], an unchecked subtraction, so a negative column
// wraps the movement BEFORE any guard here runs and the wrap passes all of
// them — the earlier version of this comment claimed a hand-built Report's
// only consequence was [ErrOverflow], and an audit disproved it by producing a
// sign-inverted closing entry that [journal.Book.Post] accepts with no error
// at all. See [ErrNegativeColumns] for the mechanism.
//
// [Derive] emits a row only for a code the window actually touched: an account
// with no movement is ABSENT, not a zero row. Over a chart of 10 000 with
// three active accounts that is three rows, and the alternative is paying
// statements' full MaxRows cost to report nothing.
type Activity struct {
	Code    string
	Name    string
	Kind    journal.Kind
	Debits  int64
	Credits int64
}

// Movement returns the period movement in the account's NORMAL direction, so
// a revenue account that earned reads positive and a contra movement reads
// negative.
//
// It is journal's own definition, reached by handing journal the two columns
// rather than re-deriving the normal-balance rule here. One definition of
// which kinds are debit-normal, in the package that owns it.
//
// Inheriting that definition means inheriting its arithmetic: Balance
// subtracts without a check, so on a row with a NEGATIVE column — which only a
// hand-built Report can hold — this wraps and returns a plausible wrong
// number. It is left unchecked rather than given an error return, because a
// two-value Movement would have to be handled at four call sites to defend one
// input class that [Report.ClosingEntry] refuses outright. The guard is at the
// boundary; see [ErrNegativeColumns].
func (a Activity) Movement() int64 {
	return journal.Account{Kind: a.Kind, Debits: a.Debits, Credits: a.Credits}.Balance()
}

// RawDelta returns Debits-Credits regardless of kind. Summed over every row of
// a report derived from balanced entries it is exactly zero, which is what
// makes it useful for a consistency check and wrong for a report.
func (a Activity) RawDelta() int64 { return a.Debits - a.Credits }

// CrossReversal is an in-window reversal whose original entry is dated outside
// the window: the period carries a correction to activity it never contained.
//
// Total is the reversal's debit total ([journal.Entry.Total]), which is its
// magnitude on both sides because journal only accepts balanced entries.
type CrossReversal struct {
	ID         uint64
	ReversalOf uint64
	Total      int64
}

// Report is one window's activity. Every slice is freshly allocated by
// [Derive] on every call and is never nil, so the caller owns it and an empty
// result is an empty slice rather than a nil to be distinguished from one.
type Report struct {
	// Window is the window the figures are for, echoed back so a stored
	// report cannot be read without it.
	Window Window

	// Activity is per-account period movement, in CHART order — which the
	// chart precondition makes ascending by Code — for codes the window
	// touched.
	Activity []Activity

	// Entries is how many entries fell in the window. Zero is a legitimate
	// report of a quiet period, not an error.
	Entries int

	// FirstID and LastID are the lowest and highest IDs IN THE WINDOW, or
	// both zero when Entries is zero. They are min and max over the
	// in-window SUBSET and not the ends of the supplied slice: over entries
	// 1, 2, 3 with only 2 in the window, both read 2.
	FirstID uint64
	LastID  uint64

	// PeriodRevenue and PeriodExpenses are the natural-sign period totals of
	// the two nominal kinds. The names carry the word PERIOD for the same
	// reason statements' carry CUMULATIVE: a reader who takes one for the
	// other misreads every figure.
	PeriodRevenue  int64
	PeriodExpenses int64

	// PeriodNet is PeriodRevenue - PeriodExpenses: the period income
	// statement's bottom line, which no cumulative report can produce.
	PeriodNet int64

	// Reversals counts in-window reversals whose original is also in-window.
	Reversals int

	// CrossWindowReversals lists in-window reversals whose original is dated
	// outside the window, in the order the entries were walked.
	CrossWindowReversals []CrossReversal

	// UnresolvedReversals lists the IDs of in-window reversals whose original
	// is absent from the supplied entries, so they could be classified
	// neither way. See the package doc: this is the bucket that must not be
	// collapsed.
	UnresolvedReversals []uint64
}

// ActivityIn counts the rows presented in sec.
//
// The section is recomputed from each row's Kind through
// [statements.SectionOf] rather than stored, so there is one definition of the
// three-bucket partition and no second field that could disagree with it. A
// Report built by hand can hold a row with an invalid Kind; such a row is
// counted in no section, and [Derive] cannot produce one.
//
// It deliberately does NOT check [ErrNegativeColumns], unlike
// [Report.ClosingEntry], and has no error return to do it with. The reason is
// that it reads no column: the count depends on Kind alone, so a negative
// column cannot make this answer wrong. A guard added here for symmetry would
// be a check that can never change an outcome — the vacuous-true shape this
// portfolio refuses elsewhere — and the honest version is this sentence.
func (r Report) ActivityIn(sec statements.Section) int {
	n := 0
	for _, a := range r.Activity {
		got, err := statements.SectionOf(a.Kind)
		if err != nil {
			continue
		}
		if got == sec {
			n++
		}
	}
	return n
}

// Derive computes the period report.
//
// It is a pure function of its three arguments: the same inputs always give
// the same Report, and nothing about the caller, the chain or the time enters
// it. On any error the returned Report is the zero value, so a caller that
// ignores the error reads zeros rather than a half-summed period.
//
// Preconditions, each for a reason given in the package doc: w must be valid;
// chart must be strictly ascending by Code and no longer than [MaxAccounts],
// with every Kind one of journal's five; entries must be strictly ascending by
// ID and no longer than [MaxEntries], with at most
// [journal.MaxPostingsPerEntry] postings each.
//
// Entries outside w are skipped, not refused — a caller passing the whole book
// is the expected case — and their postings are therefore NOT content-checked,
// because no figure in the report depends on them. [ErrInvalidPosting] and
// [ErrUnknownAccount] are scoped to the window for that reason; the
// postings-per-entry cap is not, since it is what makes [MaxEntries]' cost
// ceiling a bound rather than a hope.
func Derive(chart []journal.Account, entries []journal.Entry, w Window) (Report, error) {
	if !w.Valid() {
		return Report{}, ErrInvalidWindow
	}
	if len(chart) > MaxAccounts {
		return Report{}, ErrTooManyAccounts
	}
	if len(entries) > MaxEntries {
		return Report{}, ErrTooManyEntries
	}

	// Both preconditions are established in full BEFORE any figure is
	// computed, because the lookups below are binary searches and a search
	// over a half-validated slice is only sound by argument. An empty first
	// code fails the ascending test on its own, prev starting at "".
	prevCode := ""
	for _, a := range chart {
		if a.Code <= prevCode {
			return Report{}, ErrChartNotOrdered
		}
		prevCode = a.Code
		if !a.Kind.Valid() {
			return Report{}, ErrInvalidKind
		}
	}

	var prevID uint64
	for _, e := range entries {
		if e.ID <= prevID {
			return Report{}, ErrEntriesNotOrdered
		}
		prevID = e.ID
		// Checked for every entry, in or out of window, because this is the
		// bound MaxEntries' cost ceiling is stated against. The posting
		// CONTENT checks below are scoped to the window instead, since they
		// are about the figures rather than about the cost.
		if len(e.Postings) > journal.MaxPostingsPerEntry {
			return Report{}, ErrTooManyPostings
		}
	}

	// Period columns, parallel to chart by index. A map would be the obvious
	// structure and no /p/ in this portfolio uses one; the chart precondition
	// makes a binary search enough.
	debits := make([]int64, len(chart))
	credits := make([]int64, len(chart))

	rep := Report{
		Window:               w,
		Activity:             []Activity{},
		CrossWindowReversals: []CrossReversal{},
		UnresolvedReversals:  []uint64{},
	}

	for _, e := range entries {
		if !w.Contains(e.At) {
			continue
		}

		for _, p := range e.Postings {
			if !p.Side.Valid() || p.Amount <= 0 {
				return Report{}, ErrInvalidPosting
			}
			at := indexOfCode(chart, p.Account)
			if at < 0 {
				return Report{}, ErrUnknownAccount
			}
			var ok bool
			if p.Side == journal.Debit {
				debits[at], ok = checkedAdd(debits[at], p.Amount)
			} else {
				credits[at], ok = checkedAdd(credits[at], p.Amount)
			}
			if !ok {
				return Report{}, ErrOverflow
			}
		}

		if rep.Entries == 0 || e.ID < rep.FirstID {
			rep.FirstID = e.ID
		}
		if e.ID > rep.LastID {
			rep.LastID = e.ID
		}
		rep.Entries++

		if !e.IsReversal() {
			continue
		}
		orig := indexOfID(entries, e.ReversalOf)
		switch {
		case orig < 0:
			rep.UnresolvedReversals = append(rep.UnresolvedReversals, e.ID)
		case w.Contains(entries[orig].At):
			rep.Reversals++
		default:
			rep.CrossWindowReversals = append(rep.CrossWindowReversals, CrossReversal{
				ID:         e.ID,
				ReversalOf: e.ReversalOf,
				Total:      e.Total(),
			})
		}
	}

	for i, a := range chart {
		if debits[i] == 0 && credits[i] == 0 {
			continue
		}
		row := Activity{
			Code:    a.Code,
			Name:    a.Name,
			Kind:    a.Kind,
			Debits:  debits[i],
			Credits: credits[i],
		}
		rep.Activity = append(rep.Activity, row)

		sec, err := statements.SectionOf(a.Kind)
		if err != nil {
			return Report{}, ErrInvalidKind
		}
		if sec != statements.SectionPerformance {
			continue
		}
		var ok bool
		if a.Kind == journal.Revenue {
			rep.PeriodRevenue, ok = checkedAdd(rep.PeriodRevenue, row.Movement())
		} else {
			rep.PeriodExpenses, ok = checkedAdd(rep.PeriodExpenses, row.Movement())
		}
		if !ok {
			return Report{}, ErrOverflow
		}
	}

	net, ok := checkedSub(rep.PeriodRevenue, rep.PeriodExpenses)
	if !ok {
		return Report{}, ErrOverflow
	}
	rep.PeriodNet = net

	return rep, nil
}

// MustDerive is [Derive] and panics instead of returning an error. It is for a
// realm's mutating path, where an error return does not revert the transaction
// and only a panic does.
func MustDerive(chart []journal.Account, entries []journal.Entry, w Window) Report {
	rep, err := Derive(chart, entries, w)
	if err != nil {
		panic(err)
	}
	return rep
}

// ClosingEntry returns the postings that zero every nominal account's PERIOD
// MOVEMENT and carry the net to equityCode — the entry [journal.Book.Close]
// deliberately does not make, Close being a backdating seal and nothing else.
//
// Nominal means [statements.SectionPerformance]: the partition is read through
// [statements.SectionOf] rather than restated as a second list of kinds.
//
// The result is a PROPOSAL. This package holds no Book and posts nothing, and
// three consequences follow that a caller must own:
//
//   - It sweeps period movement, not cumulative balance. Posting it twice for
//     one window double-sweeps the period, and nothing here can detect that.
//   - A window the book has already sealed is still reportable — Close refuses
//     writes, not reads — so these postings may come back
//     [journal.ErrPeriodClosed]. That is journal's call; this package cannot
//     see the seal and does not pre-empt it.
//   - equityCode is checked for being empty, over-long, or one of the nominal
//     codes being swept ([ErrEquityCodeIsNominal]). It CANNOT be checked for
//     naming an Equity-kind account, because Report does not retain the chart:
//     a code naming a known liability yields an entry journal will accept and
//     that files net income in the wrong place. journal rejects an unknown
//     code on its own; the wrong-kind case is the caller's.
//
// The postings always balance and always carry both a debit and a credit when
// there are any at all, which is why a non-error return is always postable on
// those grounds. Net income is credited to equity and a net loss is debited,
// equity being credit-normal. A window with no nominal movement is
// [ErrNothingToClose] rather than an empty slice.
//
// That postability claim rests on a precondition [Derive] supplies for free
// and a hand-built Report does not, so this function establishes it itself:
// every row's columns must be non-negative, or [ErrNegativeColumns]. Without
// the check the claim is false in the worst available way — not an error, but
// a balanced, postable, SIGN-INVERTED entry. See [ErrNegativeColumns].
func (r Report) ClosingEntry(equityCode string) ([]journal.Posting, error) {
	if equityCode == "" || len(equityCode) > journal.MaxCodeLen {
		return nil, ErrInvalidEquityCode
	}

	out := []journal.Posting{}
	var net int64
	for _, a := range r.Activity {
		// Before the partition, not after it. A negative column on a
		// non-nominal row cannot affect this result, so checking only the
		// nominal rows would be sufficient for the arithmetic and useless as a
		// claim: the guarantee worth having is "ClosingEntry refuses any
		// Report carrying a negative column", which a reader can state and a
		// test can prove, rather than "refuses one in the rows it happened to
		// reach".
		if a.Debits < 0 || a.Credits < 0 {
			return nil, ErrNegativeColumns
		}

		sec, err := statements.SectionOf(a.Kind)
		if err != nil {
			return nil, ErrInvalidKind
		}
		if sec != statements.SectionPerformance {
			continue
		}
		if a.Code == equityCode {
			return nil, ErrEquityCodeIsNominal
		}

		m := a.Movement()
		if m == 0 {
			continue
		}
		// This branch is UNREACHABLE as the function now stands, and shipping
		// it is deliberate rather than an oversight. magnitude only refuses
		// minInt64, and with both columns proven non-negative above no single
		// row can produce it: Credits-Debits = minInt64 would need a Debits of
		// 2^63, which no int64 holds. It was reachable before
		// ErrNegativeColumns existed. It stays because it is the fail-closed
		// backstop if that guard is ever weakened, and because deleting it
		// would make this the only magnitude call site without one. The
		// REACHABLE overflow is the net accumulator below, which can reach
		// minInt64 by accumulation; the test names which door it uses.
		amt, ok := magnitude(m)
		if !ok {
			return nil, ErrOverflow
		}

		// Close the account by posting against its movement: the opposite of
		// its normal side when it moved normally, its normal side when it
		// moved contra.
		side := journal.Debit
		if a.Kind.IsDebitNormal() == (m > 0) {
			side = journal.Credit
		}
		out = append(out, journal.Posting{Account: a.Code, Side: side, Amount: amt})

		if a.Kind == journal.Revenue {
			net, ok = checkedAdd(net, m)
		} else {
			net, ok = checkedSub(net, m)
		}
		if !ok {
			return nil, ErrOverflow
		}
	}

	if net != 0 {
		amt, ok := magnitude(net)
		if !ok {
			return nil, ErrOverflow
		}
		side := journal.Credit
		if net < 0 {
			side = journal.Debit
		}
		out = append(out, journal.Posting{Account: equityCode, Side: side, Amount: amt})
	}

	if len(out) == 0 {
		return nil, ErrNothingToClose
	}
	if len(out) > journal.MaxPostingsPerEntry {
		return nil, ErrTooManyNominalAccounts
	}
	return out, nil
}

// indexOfCode returns the index of code in chart, or -1. chart is strictly
// ascending by Code, which Derive has already established, so this is a binary
// search.
func indexOfCode(chart []journal.Account, code string) int {
	lo, hi := 0, len(chart)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		switch {
		case chart[mid].Code == code:
			return mid
		case chart[mid].Code < code:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return -1
}

// indexOfID returns the index of the entry with the given ID, or -1. entries
// is strictly ascending by ID, which Derive establishes over the WHOLE slice
// before computing anything, so the search is sound by precondition rather
// than by an argument about which IDs a reversal can name.
func indexOfID(entries []journal.Entry, id uint64) int {
	lo, hi := 0, len(entries)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		switch {
		case entries[mid].ID == id:
			return mid
		case entries[mid].ID < id:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return -1
}

// minInt64 is the one int64 whose negation is not an int64.
const minInt64 int64 = -1 << 63

// magnitude returns the absolute value of v and reports whether it fit. It is
// not -v: negating [minInt64] overflows on its own, so the check has to come
// first.
func magnitude(v int64) (int64, bool) {
	if v >= 0 {
		return v, true
	}
	if v == minInt64 {
		return 0, false
	}
	return -v, true
}

// checkedAdd returns a+b and reports whether the addition did not overflow
// int64. journal's and statements' copies are both unexported, so this is a
// deliberate three-line duplicate of a trivial helper — a different thing from
// a second copy of the nominal-account partition, which is why
// [statements.SectionOf] is imported instead of restated.
func checkedAdd(a, b int64) (int64, bool) {
	sum := a + b
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}

// checkedSub returns a-b and reports whether the subtraction did not overflow
// int64. It is not checkedAdd(a, -b), for magnitude's reason.
func checkedSub(a, b int64) (int64, bool) {
	diff := a - b
	if (b < 0 && diff < a) || (b > 0 && diff > a) {
		return 0, false
	}
	return diff, true
}

// Package cashflow derives a DIRECT-METHOD statement of cash flows from a
// double-entry book: how cash moved over one window, split into operating,
// investing and financing activity, with an explicit refusal where the split
// is not determinate.
//
// It is the third primary financial statement. [p/statements] derives the
// other two from a chart at an instant, and [p/periods] derives one window's
// movement; all three of those packages carry a note saying they do not do
// this one, and all three say the INDIRECT method needs a cash-vs-accrual
// classification [journal.Posting] does not carry. That is true. The direct
// method needs something different and smaller: a declaration of which chart
// codes hold cash. A declaration is something a caller can supply, which is
// what makes this package possible without changing what a posting is.
//
// # The sign convention, and why cash must be an asset
//
// A debit to a cash account is an INFLOW and a credit is an OUTFLOW. That
// follows from cash being debit-normal, so [Policy] requires every declared
// cash code to be a [journal.Asset] and refuses anything else
// ([ErrCashAccountNotAsset]). Declaring a credit-normal account as cash would
// invert every figure in the report and nothing downstream could tell. The
// cost of the rule is real and is stated rather than hidden: a bank overdraft
// carried as a liability cannot be declared as cash, and a caller holding one
// must carry it as a contra-asset or leave it out.
//
// # Attribution is per ENTRY, never per leg
//
// This is the package's central correctness decision, and the natural design
// is wrong in a way that produces numbers which balance. Take one ordinary
// part-paid purchase:
//
//	debit  Inventory          100
//	credit Cash                60
//	credit AccountsPayable     40
//
// Classifying each non-cash leg and attributing its own amount reports 100 of
// inventory-related outflow against the 60 of cash that actually moved. It
// invents a cash flow of 40 that did not happen, and the statement still adds
// up. So the unit of attribution is the entry:
//
//   - An entry with NO cash legs is skipped. It is accrual-only and moved no
//     cash. This is the direct method's whole point.
//   - An entry whose net cash movement is ZERO is named in [Report.NetZero]
//     and not classified. A transfer between two declared cash accounts is the
//     common case; there is nothing to attribute, so determinacy is not
//     demanded of it.
//   - Otherwise the entry's net cash movement is computed from its CASH legs
//     alone — so the figure is what actually moved — and that whole figure is
//     attributed to one category.
//
// # The determinacy rule, stated as a refusal
//
// An entry touching cash is determinate iff it has at least one non-cash leg
// and all of its non-cash legs classify to the SAME category, in which case
// the entry's whole net cash delta goes there. Otherwise the entry is named in
// [Report.Unresolved] with the reason, and its cash delta is carried in
// [Report.Unattributed].
//
// The "at least one" clause is not pedantry. An entry with nonzero net cash
// and no non-cash leg at all cannot come out of a balanced book, and it gets
// its own [ReasonUnbalanced] rather than being reported as a conflict with
// nothing to conflict — see that constant.
//
// Under that rule the purchase above is determinate when Inventory and
// AccountsPayable both classify operating: 60 of operating outflow, which is
// right. An entry that settles a loan and buys equipment at once — one leg
// financing, one investing — is NOT determinate, and no apportionment is
// invented for it. Splitting it proportionally would be a guess wearing a
// number's clothes.
//
// # Why classification is per CODE and not per journal.Kind
//
// A mapping from [journal.Kind] to a category would need no caller
// declaration at all, and it is the first design anyone reaches for. It is
// wrong on the most common accounts in any book: receivables and inventory are
// assets whose movement is OPERATING, not investing, and a kind-based mapping
// puts the entire working-capital cycle in the wrong section. So there is no
// kind-based default and no default bucket of any sort. A non-cash account
// with no declared category makes its entry unresolved
// ([ReasonUndeclared]) — silence is not assent.
//
// # What this package does not do
//
//   - **It never writes, and never sees a Book.** [Derive] returns figures;
//     the caller owns persistence and idempotence.
//   - **It cannot verify the policy.** Which codes hold cash and what each
//     other code's movement means are caller declarations. A chart that
//     declares a receivable as cash produces a plausible, wrong statement.
//     The declaration is the trust boundary.
//   - **It cannot verify the opening balance.** A window-filtered entry slice
//     carries period movement, not a cumulative position, so [Report.Opening]
//     is echoed back exactly as supplied and [Report.Closing] is only as good
//     as it. This is [p/periods]' limitation inherited, not a new one.
//   - **No reversal handling.** A reversing entry that touches cash moved
//     cash, and is classified like any other entry. That differs from
//     [p/periods], where an unresolved reversal is a census item, and the
//     difference is deliberate: a cash-flow statement reports movement, and a
//     reversal's movement is movement.
//   - **No paging and no merge.** [MaxEntries] is the hard bound. Merging
//     reports across pages would make the unresolved set an artifact of the
//     paging rather than of the data.
//   - **No audit.** Every figure is derived from what the caller supplied. A
//     chart from one book and entries from another produce a plausible report
//     and nothing here detects it.
//   - **Reconciling against [p/periods] proves nothing about the split.**
//     Comparing [Report.NetChange] with the cash accounts' movement in a
//     periods report is an arithmetic self-check that both packages added the
//     same columns the same way. A statement that files every flow under the
//     wrong category reconciles perfectly.
//
// [p/journal]: /p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/journal
// [p/periods]: /p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/periods
// [p/statements]: /p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/statements
package cashflow

import (
	"errors"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/journal"
	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/periods"
)

// MaxAccounts bounds the chart [Derive] will accept. It is periods' bound,
// which is statements' bound, which is journal's own account cap — one
// number, declared once, so a chart that clears one of these packages clears
// all three.
const MaxAccounts = periods.MaxAccounts

// MaxEntries bounds the entry slice [Derive] will walk. It is periods' bound
// for the same reason: a caller feeding the same window to both packages must
// not have one of them refuse what the other accepted.
const MaxEntries = periods.MaxEntries

// NumCategories is how many categories a statement of cash flows has, and so
// the length [Report.Lines] always has. It is a constant of the standard, not
// a configuration.
const NumCategories = 3

var (
	// ErrInvalidWindow is a window failing [periods.Window.Valid].
	ErrInvalidWindow = errors.New("cashflow: invalid window")

	// ErrTooManyAccounts is a chart longer than [MaxAccounts].
	ErrTooManyAccounts = errors.New("cashflow: chart length exceeds MaxAccounts")

	// ErrChartNotSorted is a chart whose codes are not strictly ascending.
	// Membership here is a binary search, so the ordering is load-bearing
	// rather than cosmetic.
	ErrChartNotSorted = errors.New("cashflow: chart codes not strictly ascending")

	// ErrInvalidKind is a chart row whose Kind is outside journal's five.
	ErrInvalidKind = errors.New("cashflow: invalid account kind")

	// ErrTooManyEntries is an entry slice longer than [MaxEntries].
	ErrTooManyEntries = errors.New("cashflow: entry count exceeds MaxEntries")

	// ErrEntriesNotSorted is an entry slice not strictly ascending by ID.
	ErrEntriesNotSorted = errors.New("cashflow: entry IDs not strictly ascending")

	// ErrTooManyPostings is an entry with more than
	// [journal.MaxPostingsPerEntry] postings. journal cannot produce one, and
	// re-checking is what makes [MaxEntries]'s cost bound a proven ceiling
	// rather than a hope.
	ErrTooManyPostings = errors.New("cashflow: entry exceeds journal.MaxPostingsPerEntry")

	// ErrInvalidPosting is an in-window posting with an invalid Side or a
	// non-positive Amount. journal carries direction in Side and amounts are
	// always positive, so a signed amount here is a posting from somewhere
	// else.
	ErrInvalidPosting = errors.New("cashflow: invalid posting")

	// ErrUnknownAccount is an in-window posting naming a code absent from the
	// chart. It is scoped to the window because no figure in the report
	// depends on an entry outside it.
	ErrUnknownAccount = errors.New("cashflow: posting names an account absent from the chart")

	// ErrNoCashAccounts is an empty [Policy.Cash]. A statement of cash flows
	// over a book with no declared cash is all zeroes and looks exactly like
	// a quiet period, so the empty declaration is refused rather than
	// reported.
	ErrNoCashAccounts = errors.New("cashflow: policy declares no cash accounts")

	// ErrCashNotSorted is a [Policy.Cash] not strictly ascending.
	ErrCashNotSorted = errors.New("cashflow: policy cash codes not strictly ascending")

	// ErrUnknownCashAccount is a declared cash code absent from the chart.
	ErrUnknownCashAccount = errors.New("cashflow: policy declares a cash account absent from the chart")

	// ErrCashAccountNotAsset is a declared cash code whose chart Kind is not
	// [journal.Asset]. See the package doc on the sign convention: this is
	// what keeps a debit to cash meaning an inflow.
	ErrCashAccountNotAsset = errors.New("cashflow: policy declares a non-asset account as cash")

	// ErrRulesNotSorted is a [Policy.Rules] not strictly ascending by Code.
	ErrRulesNotSorted = errors.New("cashflow: policy rule codes not strictly ascending")

	// ErrInvalidCategory is a category outside the declared three — in a
	// policy rule, or passed to [Report.Line].
	ErrInvalidCategory = errors.New("cashflow: unknown category")

	// ErrUnknownRuleAccount is a policy rule naming a code absent from the
	// chart.
	ErrUnknownRuleAccount = errors.New("cashflow: policy rule names an account absent from the chart")

	// ErrCashAccountClassified is a code declared both as cash and as a
	// classified account. The two roles are exclusive: a cash account is what
	// MOVES, and a classified account is what the movement is FOR. Accepting
	// both would make the same code answer two different questions in one
	// entry.
	ErrCashAccountClassified = errors.New("cashflow: code is declared as cash and also classified")

	// ErrOverflow is an int64 overflow in any accumulation, including the
	// entry-level cash total and the closing balance.
	ErrOverflow = errors.New("cashflow: int64 overflow")
)

// Category is which activity a cash flow belongs to. The zero value is
// deliberately invalid, so a forgotten field is an error rather than
// operating activity — which is the bucket a defaulting implementation would
// pick and the one that would hide the most.
//
// The constants carry a Category prefix for the same reason
// [statements.Section]'s do: a bare Operating would read as a field name.
type Category uint8

// The three activity categories of a statement of cash flows.
const (
	CategoryOperating Category = 1 // trading: the working-capital cycle
	CategoryInvesting Category = 2 // long-lived assets and investments
	CategoryFinancing Category = 3 // capital and borrowings
)

// Valid reports whether c is one of the three categories.
func (c Category) Valid() bool {
	return c >= CategoryOperating && c <= CategoryFinancing
}

// String returns the category's name, or "invalid" for the zero value and any
// unrecognised code.
func (c Category) String() string {
	switch c {
	case CategoryOperating:
		return "operating"
	case CategoryInvesting:
		return "investing"
	case CategoryFinancing:
		return "financing"
	}
	return "invalid"
}

// Reason is why [Derive] would not classify an entry. The zero value is
// deliberately invalid.
type Reason uint8

// The three reasons an entry is unresolved.
const (
	// ReasonConflict is an entry whose non-cash legs classify to more than
	// one category. [Unresolved.Categories] names them, and names at least
	// two.
	ReasonConflict Reason = 1

	// ReasonUndeclared is an entry with a non-cash leg whose account has no
	// policy rule. [Unresolved.Codes] names them. An undeclared account is
	// named rather than defaulted, because a default bucket turns a missing
	// declaration into a figure nobody questions.
	//
	// It takes precedence over [ReasonConflict] when an entry has both an
	// undeclared code and two declared categories, because the undeclared
	// code is the actionable half: declaring it may resolve the entry, and
	// reporting a conflict while concealing a missing declaration would send
	// the reader to re-examine a policy that is not yet complete.
	ReasonUndeclared Reason = 2

	// ReasonUnbalanced is an entry all of whose legs are declared cash
	// accounts and whose cash legs do not net to zero.
	//
	// [journal.Book] cannot produce one: a balanced entry whose every leg is
	// cash has equal debits and credits over cash and therefore nets to zero,
	// which makes it a [Report.NetZero] item instead. So this reason is
	// reachable only from a hand-built entry slice, the same class
	// [p/periods] documents for its own hand-built Report.
	//
	// It exists rather than being folded into [ReasonConflict] because a
	// conflict carrying an EMPTY [Unresolved.Categories] is indistinguishable
	// from a bug in this package, and a census item a reader cannot tell from
	// a defect is not a census item. Found by writing the test for the
	// conflict case, not by reading the code.
	ReasonUnbalanced Reason = 3
)

// Valid reports whether r is one of the three reasons.
func (r Reason) Valid() bool { return r >= ReasonConflict && r <= ReasonUnbalanced }

// String returns the reason's name, or "invalid".
func (r Reason) String() string {
	switch r {
	case ReasonConflict:
		return "conflict"
	case ReasonUndeclared:
		return "undeclared"
	case ReasonUnbalanced:
		return "unbalanced"
	}
	return "invalid"
}

// Classification is one account code's activity category, declared by the
// caller. See the package doc on why this is per code rather than per
// [journal.Kind].
type Classification struct {
	Code     string
	Category Category
}

// Policy is the caller's whole declaration: which chart codes hold cash, and
// what each other code's movement is for.
//
// Both slices must be strictly ascending by code, because membership is a
// binary search in [Derive]'s inner loop. The two sets must be disjoint
// ([ErrCashAccountClassified]). Neither is verified against anything but the
// chart — this package cannot know whether a code called "petty cash" holds
// cash, and says so in its doc rather than pretending the name is evidence.
type Policy struct {
	// Cash is the codes that hold cash, strictly ascending. Must be
	// non-empty, and every code must be a [journal.Asset] in the chart.
	Cash []string

	// Rules is the activity category for non-cash codes, strictly ascending
	// by Code. A code absent from here is NOT defaulted; an entry touching it
	// is unresolved with [ReasonUndeclared].
	Rules []Classification
}

// Line is one category's gross flows over the window.
//
// Inflows and Outflows are both non-negative AS PRODUCED BY [Derive], and
// gross rather than netted, because a category with 1,000 in and 1,000 out is
// not the same business as one with nothing happening and a net of zero is
// all a netted figure can say about either.
type Line struct {
	Category Category

	// Inflows is the gross cash received, non-negative.
	Inflows int64

	// Outflows is the gross cash paid, non-negative.
	Outflows int64

	// Entries is how many in-window entries were attributed here.
	Entries int
}

// Net returns Inflows minus Outflows.
//
// The subtraction is unchecked, and that is safe for any Line [Derive]
// produces: both columns are non-negative, so the difference is in range for
// every pair of int64 values they can hold. A hand-built Line with a negative
// column can wrap, and that is the only way it can.
//
// The wrapped value does not stay local, which is the part worth stating:
// [Report.Reconciles] sums Net() over the lines, and a wrapped Net() can make
// it agree over a report whose columns say something else entirely. So
// Reconciles refuses a negative column outright rather than summing it — see
// the guard there. Net() itself stays unchecked because it has no way to
// report a refusal and a Line is a figure, not a claim.
//
// This note previously compared the blast radius to
// [periods.Activity.Movement] and said that one was wider because a negative
// column there also inverts a sign convention. That comparative was wrong,
// and an audit of this package found it: both wrap a figure that then passes
// every downstream guard, and the real asymmetry is in where the wrapped
// value GOES, not in sign inversion. The note is kept, corrected, because the
// equivalent note in periods was also once wrong about its own blast radius
// and also had to be found by an audit — twice is a pattern, and the pattern
// is that a comparative claim about another package's hazard is the sentence
// nothing checks.
func (l Line) Net() int64 { return l.Inflows - l.Outflows }

// Unresolved is one in-window entry [Derive] would not classify. It is a
// census item, not an error: the entry's cash movement is real and is carried
// in [Report.Unattributed], so [Report.NetChange] and [Report.Closing] stay
// true even when the split is incomplete.
//
// Whether an entry here SHOULD have been classifiable is an accounting
// judgement made outside this package. What is reported is that this policy
// could not decide it, and exactly what was missing or in conflict.
type Unresolved struct {
	// EntryID is the entry's journal ID.
	EntryID uint64

	// Reason is why it could not be classified.
	Reason Reason

	// Net is the entry's net cash movement: positive for an inflow. Reported
	// so a reader can see the size of what is unattributed rather than only
	// that something is.
	Net int64

	// Categories is the conflicting set, ascending and of length at least
	// two, when Reason is [ReasonConflict]; empty otherwise. Freshly
	// allocated and never nil.
	//
	// Ascending rather than in posting order, so that two records of the same
	// conflict compare equal whichever leg was posted first.
	Categories []Category

	// Codes is the undeclared account codes, in posting order and
	// deduplicated, when Reason is [ReasonUndeclared]; empty otherwise.
	// Freshly allocated and never nil.
	//
	// Posting order rather than ascending, because these are a worklist for
	// whoever extends the policy and the order a reader meets them in the
	// entry is the more useful one. The two slices differ on this
	// deliberately: a conflict set is compared, a code list is worked
	// through.
	Codes []string
}

// Report is one window's statement of cash flows. Every slice is freshly
// allocated by [Derive] on every call and is never nil, so the caller owns it
// and an empty result is an empty slice rather than a nil to be distinguished
// from one.
//
// The invariant that makes the report readable when the split is incomplete:
//
//	sum(Lines[i].Net()) + Unattributed == NetChange
//	Opening + NetChange             == Closing
//
// Both hold on every Report [Derive] returns, including one with unresolved
// entries. [Report.Reconciles] asserts the first.
type Report struct {
	// Window is the window the figures are for, echoed back so a stored
	// report cannot be read without it.
	Window periods.Window

	// Lines is the three categories, ascending by Category, always present
	// and always of length [NumCategories] — a category with no activity is a
	// zero line, not an absent one, because a statement of cash flows with a
	// missing section is not a statement of cash flows. Use [Report.Line] to
	// reach one by category rather than indexing by arithmetic.
	Lines []Line

	// Opening is the caller-supplied opening cash position, echoed back
	// unchanged. This package cannot verify it; see the package doc. A
	// negative value is accepted — an overdrawn position is a real one — so
	// the sign is not constrained here.
	Opening int64

	// NetChange is the window's total net cash movement, attributed and
	// unattributed together. It is the book's figure, not the statement's, so
	// it is true even when the split is not complete.
	NetChange int64

	// Unattributed is the net cash movement of the entries in Unresolved.
	// Zero exactly when every entry that moved cash was classified.
	Unattributed int64

	// Closing is Opening plus NetChange.
	Closing int64

	// Entries is how many entries fell in the window, including the ones that
	// moved no cash. Zero is a legitimate report of a quiet period, not an
	// error.
	Entries int

	// CashEntries is how many in-window entries touched a declared cash
	// account at all, including the ones in NetZero and Unresolved.
	CashEntries int

	// NetZero is the IDs of in-window entries that touched cash but moved
	// none on net — a transfer between two declared cash accounts, possibly
	// alongside non-cash legs. Classification is deliberately not attempted:
	// there is nothing to attribute, so demanding determinacy of them would
	// manufacture unresolved entries out of non-events.
	NetZero []uint64

	// Unresolved is the entries whose category was not determinate.
	Unresolved []Unresolved
}

// Line returns the line for c. An invalid category is [ErrInvalidCategory];
// there is no default line.
//
// This is the accessor to use. [Report.Lines] is ordered by Category and a
// consumer could index it as Lines[c-1], but that arithmetic is a second copy
// of the ordering invariant and the kind of thing that survives a reordering
// silently.
func (r Report) Line(c Category) (Line, error) {
	if !c.Valid() {
		return Line{}, ErrInvalidCategory
	}
	for _, l := range r.Lines {
		if l.Category == c {
			return l, nil
		}
	}
	return Line{}, ErrInvalidCategory
}

// Complete reports whether every in-window entry that moved cash was
// attributed to a category.
//
// A complete report is not a correct one: completeness is a property of the
// POLICY's coverage, and a policy that classifies every account wrongly is
// complete. See the package doc.
func (r Report) Complete() bool { return len(r.Unresolved) == 0 }

// Reconciles reports whether the attributed lines plus the unattributed
// residual equal NetChange.
//
// It is offered as API rather than asserted internally because a Report can
// be built by hand, and a consumer that stores one should be able to check it
// on the way back out. On a Report from [Derive] it is always true.
//
// False means one of three things and does not distinguish them: the lines do
// not sum to NetChange, the sum overflows, or a line carries a negative
// column (which [Line.Net] would wrap). All three are "do not trust this
// report", which is the whole question a bool can answer.
func (r Report) Reconciles() bool {
	total := int64(0)
	for _, l := range r.Lines {
		// Before the sum, and the reason is that Net() cannot refuse. A
		// hand-built Line{Inflows: maxI64, Outflows: -1} nets to minI64 by
		// wrapping, and checkedAdd cannot see it: the wrap happened in the
		// subtraction, so what arrives here is an ordinary in-range negative
		// and every add is honest. Reconciles would then agree with a report
		// whose operating line advertises an inflow of maxI64 -- which is
		// worse than disagreeing, because Reconciles is the one check a
		// consumer storing a hand-built Report is told to trust.
		//
		// Derive never produces a negative column (both are accumulated from
		// zero through checkedAdd), so this costs a Derive-sourced report
		// nothing. p/periods guards the same shape at the same kind of
		// boundary, with an error rather than a bool because it has one to
		// return.
		if l.Inflows < 0 || l.Outflows < 0 {
			return false
		}
		n, ok := checkedAdd(total, l.Net())
		if !ok {
			return false
		}
		total = n
	}
	total, ok := checkedAdd(total, r.Unattributed)
	if !ok {
		return false
	}
	return total == r.NetChange
}

// Derive builds the statement for one window.
//
// Preconditions, all refused rather than assumed: w must be valid; chart must
// be strictly ascending by Code, no longer than [MaxAccounts], with every
// Kind one of journal's five; entries must be strictly ascending by ID and no
// longer than [MaxEntries], with at most [journal.MaxPostingsPerEntry]
// postings each; and p must satisfy the rules on [Policy].
//
// Entries outside w are skipped, not refused — a caller passing the whole
// book is the expected case — and their postings are therefore not
// content-checked, because no figure in the report depends on them.
// [ErrInvalidPosting] and [ErrUnknownAccount] are scoped to the window for
// that reason; the postings-per-entry cap is not, since it is what makes
// [MaxEntries]'s cost ceiling a bound rather than a hope.
func Derive(chart []journal.Account, entries []journal.Entry, w periods.Window, p Policy, opening int64) (Report, error) {
	if !w.Valid() {
		return Report{}, ErrInvalidWindow
	}
	if len(chart) > MaxAccounts {
		return Report{}, ErrTooManyAccounts
	}
	if len(entries) > MaxEntries {
		return Report{}, ErrTooManyEntries
	}
	for i, a := range chart {
		if !a.Kind.Valid() {
			return Report{}, ErrInvalidKind
		}
		if i > 0 && chart[i-1].Code >= a.Code {
			return Report{}, ErrChartNotSorted
		}
	}
	for i, e := range entries {
		if len(e.Postings) > journal.MaxPostingsPerEntry {
			return Report{}, ErrTooManyPostings
		}
		if i > 0 && entries[i-1].ID >= e.ID {
			return Report{}, ErrEntriesNotSorted
		}
	}
	if err := validatePolicy(chart, p); err != nil {
		return Report{}, err
	}

	rep := Report{
		Window:     w,
		Lines:      make([]Line, 0, NumCategories),
		Opening:    opening,
		NetZero:    make([]uint64, 0),
		Unresolved: make([]Unresolved, 0),
	}
	for c := CategoryOperating; c <= CategoryFinancing; c++ {
		rep.Lines = append(rep.Lines, Line{Category: c})
	}

	for _, e := range entries {
		if !w.Contains(e.At) {
			continue
		}
		rep.Entries++

		net := int64(0)
		cashLegs := 0
		cats := make([]Category, 0, NumCategories)
		codes := make([]string, 0)

		for _, pg := range e.Postings {
			if !pg.Side.Valid() || pg.Amount <= 0 {
				return Report{}, ErrInvalidPosting
			}
			if !inChart(chart, pg.Account) {
				return Report{}, ErrUnknownAccount
			}
			if isCash(p.Cash, pg.Account) {
				cashLegs++
				signed := pg.Amount
				if pg.Side == journal.Credit {
					signed = -pg.Amount
				}
				sum, ok := checkedAdd(net, signed)
				if !ok {
					return Report{}, ErrOverflow
				}
				net = sum
				continue
			}
			c, found := ruleFor(p.Rules, pg.Account)
			if !found {
				if !hasCode(codes, pg.Account) {
					codes = append(codes, pg.Account)
				}
				continue
			}
			if !hasCategory(cats, c) {
				cats = append(cats, c)
			}
		}

		if cashLegs == 0 {
			continue
		}
		rep.CashEntries++

		if net == 0 {
			rep.NetZero = append(rep.NetZero, e.ID)
			continue
		}

		total, ok := checkedAdd(rep.NetChange, net)
		if !ok {
			return Report{}, ErrOverflow
		}
		rep.NetChange = total

		if len(codes) > 0 || len(cats) != 1 {
			// The three cases are selected explicitly rather than by falling
			// through to a default, so that each Unresolved record carries the
			// set that explains it: Codes for a missing declaration,
			// Categories for a conflict, and NEITHER for an unbalanced
			// cash-only entry -- which is why that case has its own reason
			// rather than appearing as a conflict with an empty set.
			var reason Reason
			reported := make([]Category, 0, len(cats))
			reportedCodes := make([]string, 0, len(codes))
			switch {
			case len(codes) > 0:
				reason = ReasonUndeclared
				reportedCodes = append(reportedCodes, codes...)
			case len(cats) == 0:
				reason = ReasonUnbalanced
			default:
				reason = ReasonConflict
				reported = append(reported, sortedCategories(cats)...)
			}
			unattributed, ok := checkedAdd(rep.Unattributed, net)
			if !ok {
				return Report{}, ErrOverflow
			}
			rep.Unattributed = unattributed
			rep.Unresolved = append(rep.Unresolved, Unresolved{
				EntryID:    e.ID,
				Reason:     reason,
				Net:        net,
				Categories: reported,
				Codes:      reportedCodes,
			})
			continue
		}

		idx := int(cats[0]) - 1
		if net > 0 {
			in, ok := checkedAdd(rep.Lines[idx].Inflows, net)
			if !ok {
				return Report{}, ErrOverflow
			}
			rep.Lines[idx].Inflows = in
		} else {
			out, ok := checkedAdd(rep.Lines[idx].Outflows, -net)
			if !ok {
				return Report{}, ErrOverflow
			}
			rep.Lines[idx].Outflows = out
		}
		rep.Lines[idx].Entries++
	}

	closing, ok := checkedAdd(rep.Opening, rep.NetChange)
	if !ok {
		return Report{}, ErrOverflow
	}
	rep.Closing = closing

	return rep, nil
}

// validatePolicy checks p against the chart. Every failure is a distinct
// error, because each one has a distinct fix and "invalid policy" tells a
// caller nothing about which of six things to look at.
func validatePolicy(chart []journal.Account, p Policy) error {
	if len(p.Cash) == 0 {
		return ErrNoCashAccounts
	}
	if len(p.Cash) > MaxAccounts || len(p.Rules) > MaxAccounts {
		return ErrTooManyAccounts
	}
	for i, code := range p.Cash {
		if i > 0 && p.Cash[i-1] >= code {
			return ErrCashNotSorted
		}
		k, found := kindOf(chart, code)
		if !found {
			return ErrUnknownCashAccount
		}
		if k != journal.Asset {
			return ErrCashAccountNotAsset
		}
	}
	for i, r := range p.Rules {
		if i > 0 && p.Rules[i-1].Code >= r.Code {
			return ErrRulesNotSorted
		}
		if !r.Category.Valid() {
			return ErrInvalidCategory
		}
		if _, found := kindOf(chart, r.Code); !found {
			return ErrUnknownRuleAccount
		}
		if isCash(p.Cash, r.Code) {
			return ErrCashAccountClassified
		}
	}
	return nil
}

// kindOf returns the chart Kind for code. The chart is strictly ascending, so
// this is a binary search.
func kindOf(chart []journal.Account, code string) (journal.Kind, bool) {
	lo, hi := 0, len(chart)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		switch {
		case chart[mid].Code == code:
			return chart[mid].Kind, true
		case chart[mid].Code < code:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return 0, false
}

// inChart reports whether code is in the chart.
func inChart(chart []journal.Account, code string) bool {
	_, found := kindOf(chart, code)
	return found
}

// isCash reports whether code is a declared cash account. cash is strictly
// ascending, so this is a binary search.
func isCash(cash []string, code string) bool {
	lo, hi := 0, len(cash)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		switch {
		case cash[mid] == code:
			return true
		case cash[mid] < code:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return false
}

// ruleFor returns the declared category for code. rules is strictly ascending
// by Code, so this is a binary search.
func ruleFor(rules []Classification, code string) (Category, bool) {
	lo, hi := 0, len(rules)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		switch {
		case rules[mid].Code == code:
			return rules[mid].Category, true
		case rules[mid].Code < code:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return 0, false
}

// hasCategory reports whether c is already in cats. The slice is at most
// NumCategories long, so a linear scan is the whole cost.
func hasCategory(cats []Category, c Category) bool {
	for _, x := range cats {
		if x == c {
			return true
		}
	}
	return false
}

// hasCode reports whether code is already in codes. The slice is at most
// journal.MaxPostingsPerEntry long.
func hasCode(codes []string, code string) bool {
	for _, x := range codes {
		if x == code {
			return true
		}
	}
	return false
}

// sortedCategories returns cats in ascending order, freshly allocated. The
// input is at most NumCategories long, so this is a selection over three
// values and the ordering exists so a reader comparing two Unresolved records
// is comparing sets rather than posting orders.
func sortedCategories(cats []Category) []Category {
	out := make([]Category, 0, len(cats))
	for c := CategoryOperating; c <= CategoryFinancing; c++ {
		if hasCategory(cats, c) {
			out = append(out, c)
		}
	}
	return out
}

// checkedAdd returns a+b and whether it is representable. Both operands are
// int64 and the sign test is the standard one: an overflow is exactly the
// case where two same-signed operands produce a differently-signed sum.
func checkedAdd(a, b int64) (int64, bool) {
	s := a + b
	if (a > 0 && b > 0 && s < 0) || (a < 0 && b < 0 && s >= 0) {
		return 0, false
	}
	return s, true
}

// Package payroll is employer-funded recurring salary disbursement with
// real ugnot custody.
//
// # The one idea
//
// An allowance refills; a salary ACCRUES. That single sentence is why
// this realm exists beside budgets rather than inside it.
//
// budgets (this portfolio, live on onyx-1) grants a delegate a
// rate-limited spending authority through p/spendbook: the delegate may
// draw at most PerPeriod per window, and a window that passes unused is
// gone. Use-it-or-lose-it is exactly right for a spending authority — an
// unspent budget is not a debt.
//
// A salary is the dual. An employee who does not collect for three
// periods is owed three periods. Unclaimed pay is a LIABILITY of the
// employer, not an expired permission. No refilling primitive can model
// that, because the whole point of a refill is that the previous window
// is forgotten.
//
// So the arithmetic here is accrual arithmetic, and it is the one
// genuinely new mechanism in this realm. Everything that touches coins
// is delegated to primitives this portfolio has already audited and run
// live: p/coinio for custody and payout guards, p/feeledger for
// per-employee balances and the liabilities total.
//
// # Paid in arrears
//
// A period must COMPLETE before it is owed. At the instant a position
// starts, nothing is due; the first period becomes payable at
// StartHeight + PeriodBlocks. Paying in advance would mean the realm
// disbursing for time that has not elapsed, and there is no mechanism on
// chain to take it back if the position ends early.
//
// A consequence worth stating plainly: a position whose PeriodBlocks
// never fully elapses before it is terminated pays NOTHING. That is not
// a rounding loss hidden in the implementation, it is the arrears rule
// applied honestly, and Terminate's documentation repeats it.
//
// # Accrual is permissionless, and whole-period
//
// Gno has no autonomous execution, so "recurring" always means someone
// sends a transaction later. Accrue may therefore be called by ANYONE —
// the employee, the employer, a keeper realm, a stranger. It does only
// what the employer already committed to when the position was opened,
// it moves coins from that employer's own pool to that employee's own
// ledger balance, and the caller pays the gas. There is no third party
// who gains, so there is nothing to grief with. This is also what makes
// the realm composable with upkeep, the portfolio's keeper-incentive
// realm.
//
// Accrual settles WHOLE periods only. If the pool covers two of three
// due periods, two are credited and the third stays due — it is not
// partially paid, and no capacity is burned. The pool bounds HOW MANY
// periods clear, never WHETHER a period is paid in full.
//
// # Solvency, and the lesson taken from budgets
//
// budgets' package documentation records that a budget is authority and
// not a reservation: over-authorization is legal there, and solvency is
// enforced per-owner at draw time. The same choice is made here for the
// same reason, and the honest consequence is named rather than hidden:
//
//	OPENING A POSITION DOES NOT RESERVE ANY COINS.
//
// An employer may hire more people than the pool can ever pay. Nothing
// in this realm prevents it, because a future funding transaction is a
// perfectly ordinary way to intend to meet an obligation, and refusing
// the hire would only move the problem to the moment the pool dips. What
// the realm guarantees is narrower and checkable: a period either clears
// in full or stays due, and no employee's accrued ledger balance can be
// reduced by anyone.
//
// # The monetary invariant
//
// Two statements, because one of them is a decomposition and the other is
// a solvency claim, and collapsing them is how the wrong identity gets
// written down:
//
//	Liabilities() == TotalPooled() + AccruedTotal() + FeesAccrued()
//	Held()        == Liabilities() + Surplus()
//
// Liabilities() is every coin owed to anyone: the employers' unallocated
// pools PLUS the feeledger's own total, which is itself the accrued
// employee balances plus the fee pot. Surplus() is coins pushed at the
// realm outside every entrypoint. Both lines hold after every operation
// and are pinned by TestMonetaryInvariant. It is the same shape budgets
// carries, deliberately: a reader who has checked one can check the
// other.
//
// Only the first line can fail. The second is definitional — Surplus()
// is computed as Held()-Liabilities() — so asserting it is a tautology,
// and what the test actually checks is Held() >= Liabilities() beside the
// decomposition. A reader who takes the second line for a check has been
// reassured by arithmetic.
//
// This paragraph read `Held() == TotalPooled() + Liabilities() +
// Surplus()` until the pre-deploy audit, which double-counts the pools
// because Liabilities() already contains TotalPooled(). The code was
// never wrong and payroll_test.gno encoded the right decomposition the
// whole time; the comment was, and a comment is immutable after addpkg.
//
// # Termination is two steps, and that is a protection
//
// Terminate stops the clock. Release frees the storage. They are
// separate because collapsing them would destroy earned-but-unaccrued
// pay: an employer whose pool is short could remove a position owing
// three periods and the debt would vanish with the record.
//
// So Terminate sets the end height to now and leaves the position in
// place, with whatever is due still due and still accruable by anyone.
// Release removes it, and only once nothing is due. Release is
// permissionless and the chain refunds the freed storage deposit to the
// caller, which is the standing incentive to tidy up someone else's
// settled position — the same mechanism budgets uses for Reap.
//
// # What this realm does NOT do
//
//   - It does not value work, verify it happened, or arbitrate a dispute
//     about it. A position is a standing instruction from an employer,
//     and nothing more.
//   - It holds ugnot and only ugnot.
//   - It has no admin. The deploying namespace receives protocol fees
//     and swept surplus and has no other privilege: no setter, no pause,
//     no ability to touch a pool or a balance. Funding a pool is what
//     makes an address an employer, exactly as in budgets.
//
// # STORAGE
//
// An employer record is paid for by that employer's first Fund; a
// position record by the Hire that opens it. Release removes a position
// record and the chain refunds the freed deposit to the transaction that
// frees it.
package payroll

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/coinio"
	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/feeledger"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// RealmPath is this realm's own path, used to build Render links.
const RealmPath = "/r/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/payroll"

// Denom is the only asset this realm holds.
const Denom = "ugnot"

// MaxFeeBps is the hard ceiling on any accrual fee this realm could ever
// charge, enforced by the feeledger the realm is constructed with — a
// feeBps above it is refused by the primitive's own validation, not by a
// check in this file. 500 bps = 5%.
const MaxFeeBps = int64(500)

// AccrueFeeBps is the fee charged on each accrual, on the gross amount,
// floor-rounded in the EMPLOYEE's favour: 100 bps = 1%. It matches the
// most conservative live fee in this portfolio (fee_split, crowdfund,
// budgets). It is a compile-time constant and there is no setter, so a
// position's economics cannot be changed under the employee after the
// position is opened.
const AccrueFeeBps = int64(100)

// FeeCollector receives withdrawn fees and swept surplus. Compile-time
// constant: there is no setter and no transfer path. It is the deploying
// namespace's address — stated plainly: the operator of this realm.
//
// NOTE FOR ANY RE-NAMESPACED PORT: this is the address-as-data hazard
// that a namespace substitution rewrites silently while every
// byte-comparison still reports the tree faithful, because the rewrite
// IS the intended transformation. Re-state it deliberately per chain;
// never let it be derived.
const FeeCollector = address("g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3")

// MinFunding keeps dust pools out: 1 GNOT per Fund call.
const MinFunding = int64(1_000_000)

// MinPerPeriod is the smallest salary a position may carry. Below the
// fee denominator a 1% fee floors to zero, so a per-period amount of a
// few ugnot would be a fee-free position by accident rather than by
// design; 1000 ugnot keeps the fee arithmetic meaningful.
const MinPerPeriod = int64(1_000)

// MinPeriodBlocks is the shortest period a position may use. A period of
// a handful of blocks is a rate rather than a salary, and it makes the
// arrears rule meaningless. Unlike budgets, a period of 0 is NOT
// accepted here: there is no "one lifetime window" reading of a salary,
// and dividing by it would panic.
const MinPeriodBlocks = int64(100)

// MaxRoster caps simultaneously-open positions per employer. Hire is
// permissionless to anyone with a funded pool, so this is an
// AVAILABILITY BOUND and it is documented rather than hidden: an
// employer can exhaust their OWN roster and no one else's, because the
// roster is per-employer. The cost of filling one is gas plus the
// storage deposit on every position record, held until Release.
const MaxRoster = 64

// OpenEnded is the EndHeight value meaning "no end": the position
// accrues until it is terminated.
const OpenEnded = int64(0)

type position struct {
	employer address
	employee address

	// perPeriod is the gross salary per completed period. The employee
	// receives perPeriod minus the accrual fee.
	perPeriod int64

	// periodBlocks is the period length. Periods are ANCHORED to
	// startHeight, not sliding: period k closes at
	// startHeight + k*periodBlocks.
	periodBlocks int64

	startHeight int64

	// endHeight is OpenEnded, or the height past which no further period
	// accrues. Terminate sets it to the current height.
	endHeight int64

	// paidPeriods counts whole periods already accrued. It only ever
	// increases, and it is the single source of truth for what has been
	// settled — never a coin balance, which the employee can withdraw.
	paidPeriods int64
}

var (
	self address

	// employers holds one record per address that has ever funded a
	// pool. Key is the address string.
	employers = avl.NewTree() // address string -> *employer

	// positions holds one record per open position, keyed by
	// employer|employee so a roster scan is a prefix iteration and a
	// duplicate hire is an exact-key collision.
	positions = avl.NewTree() // "employer|employee" -> *position

	// ledger holds every employee's accrued-but-unclaimed balance and
	// the fee pot. It is GLOBAL across employers on purpose: an employee
	// paid by two employers has one balance and one Claim.
	ledger = feeledger.MustNew(MaxFeeBps)
)

type employer struct {
	pool   int64
	roster int
}

func init() {
	self = unsafe.CurrentRealm().Address()
}

// rejectStraySend aborts when a direct EOA MsgCall attaches coins to a
// non-payable entrypoint. This realm holds funds, so such a send would
// become sweepable surplus, silently converting a user's coins into
// operator funds.
//
// THE PREDICATE IS NARROWER THAN THE FIRST SENTENCE OF THIS COMMENT USED
// TO BE, and the narrowing is correct rather than a gap. OriginSend()
// reports the coins attached to the ORIGINATING TRANSACTION, not coins
// this realm received in this call — there is no per-call msg.value in
// Gno. MsgCall is the one caller shape where the two coincide: the
// envelope is delivered to the realm being called. Under MsgRun the
// envelope lands in the caller's own ephemeral /e/ realm, and under a
// realm caller it lands at the first realm in the chain; in both, coins
// that genuinely reach payroll do so through an explicit SendCoins that
// OriginSend() does not describe. So widening this guard to IsUser(), or
// dropping the conjunct entirely, would refuse calls that sent payroll
// nothing while still not seeing the sends it was widened to catch. The
// stdlib guidance is explicit that OriginSend pairs with IsUserCall.
//
// What remains uncovered is therefore not a hole in this guard: coins can
// always arrive at an address by a bare MsgSend with no call at all, which
// no entrypoint check can intercept. That is exactly what Surplus() and
// SweepSurplus exist to name and reclaim.
func rejectStraySend(cur realm) {
	if !cur.IsCurrent() {
		// Every call site forwards a crossing entrypoint's own live cur,
		// so this cannot fire today; it exists so a future refactor that
		// hands this guard a stale realm value fails closed, not open
		// (coinio names IsCurrent as the guard secondary realm
		// parameters require, and this helper follows that discipline).
		panic("payroll: realm capability is not current")
	}
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this entrypoint does not accept coins")
	}
}

// --- the pool ---

// Fund adds the attached coins to the caller's own pool. Direct EOA
// calls with -send only (the receipt-guaranteed shape); exactly one
// positive ugnot coin, at least MinFunding. Anyone may fund; funding is
// what makes an address an employer.
func Fund(cur realm) int64 {
	owner, amount := coinio.Receive(0, cur, Denom)
	if amount < MinFunding {
		panic("funding is below MinFunding")
	}
	key := owner.String()
	e := getEmployer(key)
	if e == nil {
		e = &employer{}
		employers.Set(key, e)
	}
	total, ok := checkedAdd(e.pool, amount)
	if !ok {
		panic("pool would overflow")
	}
	e.pool = total
	chain.Emit("Funded", "employer", key, "amount", itoa(amount),
		"pool", itoa(e.pool))
	return e.pool
}

// WithdrawPool returns unallocated pool coins to the employer. There is
// no lock and no notice period, and that is a DOCUMENTED asymmetry
// rather than an oversight: see the package doc on solvency. An employer
// may withdraw a pool while positions are open, which leaves those
// positions accruing against an empty pool — due but unsettleable until
// the pool is refunded. What an employer can never do is reduce a
// balance already accrued to an employee's ledger account.
func WithdrawPool(cur realm, amount int64) int64 {
	rejectStraySend(cur)
	if amount <= 0 {
		panic("amount must be positive")
	}
	owner := cur.Previous().Address()
	key := owner.String()
	e := mustEmployer(key)
	if amount > e.pool {
		panic("amount exceeds pool")
	}
	// Debit before the payout, per coinio's ordering contract: a panic
	// inside coinio aborts the transaction and reverts this debit.
	e.pool -= amount
	coinio.Payout(0, cur, owner, Denom, amount)
	chain.Emit("PoolWithdrawn", "employer", key, "amount", itoa(amount),
		"pool", itoa(e.pool))
	return e.pool
}

// WithdrawPoolAll is WithdrawPool for the whole pool. It panics on an
// empty pool rather than succeeding with a zero transfer, so a caller
// cannot read success as evidence that coins moved.
func WithdrawPoolAll(cur realm) int64 {
	rejectStraySend(cur)
	owner := cur.Previous().Address()
	e := mustEmployer(owner.String())
	if e.pool == 0 {
		panic("no pool to withdraw")
	}
	return WithdrawPool(cur, e.pool)
}

// --- positions ---

// Hire opens a position. The caller is the employer and must already
// have a funded pool, which is this realm's only barrier to opening
// records at someone else's expense.
//
// startHeight must not be in the past. A backdated start would make a
// large number of periods due in the same transaction that opened the
// position, draining the pool to one employee in one call — the hire
// would look like a schedule and behave like a withdrawal. Refusing it
// is cheaper to reason about than bounding it.
//
// # perPeriod is bounded below and NOT above, and the slot cost is permanent
//
// MinPerPeriod is a floor; there is no ceiling. A position opened with a
// perPeriod larger than any pool that can be funded is unsettleable,
// because Accrue's solvency check is integer division — e.pool/perPeriod
// is 0 for every reachable pool, so Accrue panics on "cannot cover one
// period" forever. Once that position's first period completes, duePeriods
// is permanently non-zero, so Release refuses forever too, and the record
// consumes one of the employer's MaxRoster slots for good.
//
// This is a DECLARED LIMITATION rather than a defect, and the reason is
// that it is strictly self-harm: owner comes from cur.Previous().Address()
// below and is never a parameter, so no caller can open an unpayable
// position on anyone else's roster, and the pool itself stays fully
// withdrawable through WithdrawPool. The mitigation is available and
// narrow: Terminate then Release BEFORE the first period completes, while
// duePeriods is still zero. After that the slot does not come back.
func Hire(cur realm, employee address, perPeriod, periodBlocks, startHeight, endHeight int64) {
	rejectStraySend(cur)

	// The lowercase clause is load-bearing, and it is carried from budgets'
	// Grant (measured on this toolchain, not argued): address.IsValid()
	// defers to crypto.AddressFromBech32, whose decoder lowercases the
	// input BEFORE verifying the checksum, so it returns true for the
	// all-uppercase spelling of a valid address.
	//
	// HERE THE CONSEQUENCE IS WORSE THAN IN BUDGETS, which is why this is
	// not boilerplate. In budgets an uppercase delegate yields a BRICKED
	// GRANT: no coins move, the owner's pool is untouched, only a slot is
	// wasted. In payroll, Accrue would debit the employer's pool and credit
	// ledger["G1UPPER..."], while Claim authenticates against
	// cur.Previous().Address(), which is always canonical. The balance would
	// be real, owed, and unreachable by every caller — a PERMANENT LOSS of
	// the employer's coins rather than a wasted record.
	//
	// One guard of this kind is all the realm needs, and the reason is
	// structural: employee is the only caller-supplied value that ever
	// becomes a storage key here. Every other key derives from
	// cur.Previous().Address() or coinio.Receive's sender, both canonical by
	// construction, and every other entrypoint LOOKS UP a position rather
	// than creating one, so a non-canonical argument there fails closed at
	// mustPosition. The check is complete as well as necessary: that decoder
	// rejects mixed case outright, so a valid address has exactly two
	// spellings and refusing every non-lower one leaves precisely the
	// canonical one.
	if !employee.IsValid() || string(employee) != strings.ToLower(string(employee)) {
		panic("employee is not a valid address in canonical (lowercase) form")
	}
	if perPeriod < MinPerPeriod {
		panic("perPeriod is below MinPerPeriod")
	}
	if periodBlocks < MinPeriodBlocks {
		panic("periodBlocks is below MinPeriodBlocks")
	}
	now := runtime.ChainHeight()
	if startHeight < now {
		panic("startHeight is in the past")
	}
	if endHeight != OpenEnded {
		if endHeight <= startHeight {
			panic("endHeight must be after startHeight, or OpenEnded")
		}
		if endHeight-startHeight < periodBlocks {
			panic("position ends before its first period completes")
		}
	}

	owner := cur.Previous().Address()
	ownerKey := owner.String()
	e := mustEmployer(ownerKey)
	if e.pool == 0 {
		panic("fund a pool before hiring")
	}
	if e.roster >= MaxRoster {
		panic("employer roster is full")
	}
	k := posKey(owner, employee)
	if positions.Get(k) != nil {
		panic("this employee already has an open position with this employer")
	}

	positions.Set(k, &position{
		employer:     owner,
		employee:     employee,
		perPeriod:    perPeriod,
		periodBlocks: periodBlocks,
		startHeight:  startHeight,
		endHeight:    endHeight,
		paidPeriods:  0,
	})
	e.roster++
	chain.Emit("Hired", "employer", ownerKey, "employee", employee.String(),
		"perPeriod", itoa(perPeriod), "periodBlocks", itoa(periodBlocks),
		"startHeight", itoa(startHeight), "endHeight", itoa(endHeight))
}

// Accrue settles every whole period that has completed and not yet been
// paid, as far as the employer's pool reaches, and credits the gross
// minus the accrual fee to the employee's ledger balance.
//
// ANYONE may call this — see the package doc. It returns the gross
// amount settled.
func Accrue(cur realm, employer, employee address) int64 {
	rejectStraySend(cur)
	p := mustPosition(employer, employee)
	e := mustEmployer(employer.String())

	now := runtime.ChainHeight()
	due := duePeriods(p, now)
	if due == 0 {
		panic("no periods are due")
	}

	// Whole periods the pool can cover. This is the solvency check and
	// it runs BEFORE any state moves, so a pool that cannot cover even
	// one period leaves paidPeriods untouched and nothing is lost.
	affordable := e.pool / p.perPeriod
	n := due
	if affordable < n {
		n = affordable
	}
	if n == 0 {
		panic("employer's pool cannot cover one period")
	}

	gross := n * p.perPeriod // bounded by e.pool, so it cannot overflow
	e.pool -= gross
	p.paidPeriods += n
	credited, fee := ledger.MustDeposit(employee.String(), gross, AccrueFeeBps)

	chain.Emit("Accrued", "employer", employer.String(),
		"employee", employee.String(), "periods", itoa(n),
		"gross", itoa(gross), "credited", itoa(credited), "fee", itoa(fee),
		"paidPeriods", itoa(p.paidPeriods), "pool", itoa(e.pool))
	return gross
}

// Terminate stops the clock on a position. The employer only.
//
// It does NOT remove the record and does not settle anything: whatever
// was due stays due, and anyone may still Accrue it. That separation is
// the employee's protection — see the package doc. Use Release to remove
// a settled position.
//
// If the position has not yet reached its first complete period, this
// pays nothing, by the arrears rule.
func Terminate(cur realm, employee address) {
	rejectStraySend(cur)
	owner := cur.Previous().Address()
	p := mustPosition(owner, employee)
	now := runtime.ChainHeight()
	if p.endHeight != OpenEnded && p.endHeight <= now {
		panic("position has already ended")
	}
	p.endHeight = now
	chain.Emit("Terminated", "employer", owner.String(),
		"employee", employee.String(), "endHeight", itoa(now),
		"paidPeriods", itoa(p.paidPeriods), "due", itoa(duePeriods(p, now)))
}

// Release removes an ended, fully-settled position and frees its
// storage. Permissionless: the chain refunds the freed storage deposit
// to the caller, which is the standing incentive to tidy up a settled
// position that is not your own.
//
// It refuses while anything is due, which is what makes it safe to let a
// stranger call: a Release cannot destroy an unpaid obligation.
func Release(cur realm, employer, employee address) {
	rejectStraySend(cur)
	p := mustPosition(employer, employee)
	now := runtime.ChainHeight()
	if p.endHeight == OpenEnded || p.endHeight > now {
		panic("position has not ended")
	}
	if duePeriods(p, now) != 0 {
		panic("position has unsettled periods")
	}
	positions.Remove(posKey(employer, employee))
	if e := getEmployer(employer.String()); e != nil && e.roster > 0 {
		e.roster--
	}
	chain.Emit("Released", "employer", employer.String(),
		"employee", employee.String(), "paidPeriods", itoa(p.paidPeriods))
}

// --- claiming ---

// Claim pays the caller their whole accrued balance. The employee only —
// there is no "claim on behalf of", because that would let a third party
// choose the moment someone else's coins move.
func Claim(cur realm) int64 {
	rejectStraySend(cur)
	who := cur.Previous().Address()
	key := who.String()
	amount := ledger.BalanceOf(key)
	if amount == 0 {
		panic("no balance to claim")
	}
	// Debit first, per coinio's ordering contract.
	ledger.MustWithdraw(key, amount)
	coinio.Payout(0, cur, who, Denom, amount)
	chain.Emit("Claimed", "account", key, "amount", itoa(amount))
	return amount
}

// WithdrawFees moves the accrued fee pot to FeeCollector. Anyone may
// call it; the destination is a compile-time constant, so the caller
// cannot influence where the coins go.
func WithdrawFees(cur realm) int64 {
	rejectStraySend(cur)
	fees := ledger.WithdrawFees()
	if fees == 0 {
		panic("no fees accrued")
	}
	coinio.Payout(0, cur, FeeCollector, Denom, fees)
	chain.Emit("FeesWithdrawn", "to", FeeCollector.String(), "amount", itoa(fees))
	return fees
}

// SweepSurplus sends coins held beyond every obligation to FeeCollector.
// The reserve passed to coinio is the realm's full liability — pooled
// coins plus ledger liabilities — so a sweep can never reach a coin that
// an employer or an employee is owed.
func SweepSurplus(cur realm) int64 {
	rejectStraySend(cur)
	swept := coinio.Sweep(0, cur, FeeCollector, Denom, Liabilities())
	chain.Emit("Swept", "denom", Denom, "to", FeeCollector.String(),
		"amount", itoa(swept))
	return swept
}

// --- accrual arithmetic, the one new mechanism ---

// duePeriods is the number of whole periods that have completed and not
// been paid. It is a pure function of the position and the clock, which
// is what makes it unit-testable without a chain.
//
// Periods are ANCHORED to startHeight: period k closes at
// startHeight + k*periodBlocks. Nothing is due at startHeight itself —
// salary is paid in arrears.
func duePeriods(p *position, now int64) int64 {
	horizon := now
	if p.endHeight != OpenEnded && p.endHeight < horizon {
		horizon = p.endHeight
	}
	if horizon <= p.startHeight {
		return 0
	}
	completed := (horizon - p.startHeight) / p.periodBlocks
	if completed <= p.paidPeriods {
		return 0
	}
	return completed - p.paidPeriods
}

// --- read-only accessors ---

// DuePeriods is duePeriods for a live position, at the current height.
func DuePeriods(employer, employee address) int64 {
	return duePeriods(mustPosition(employer, employee), runtime.ChainHeight())
}

// DueAmount is the gross that DuePeriods would settle if the pool were
// unbounded. Read it beside AccruableAmount: the difference between them
// is exactly the employer's shortfall.
//
// It is the one arithmetic here with NO pool bound behind it, so it is the
// one place an int64 can wrap: perPeriod has no ceiling and due grows with
// the chain. Accrue cannot wrap, because its product is bounded by the
// pool it is about to debit (see the comment there). An unpayable position
// is a legal state in this realm, so the overflow is reachable in
// principle, and this panics rather than returning a negative salary —
// a view that refuses is recoverable, a view that lies is not.
func DueAmount(employer, employee address) int64 {
	p := mustPosition(employer, employee)
	gross, ok := checkedMul(duePeriods(p, runtime.ChainHeight()), p.perPeriod)
	if !ok {
		panic("due amount would overflow; read DuePeriods and PerPeriodOf instead")
	}
	return gross
}

// AccruableAmount is the gross an Accrue would settle right now, pool
// bound included. It is the honest number, and it can be less than
// DueAmount without anything being wrong — see the package doc on
// solvency.
func AccruableAmount(employer, employee address) int64 {
	p := mustPosition(employer, employee)
	e := mustEmployer(employer.String())
	due := duePeriods(p, runtime.ChainHeight())
	affordable := e.pool / p.perPeriod
	if affordable < due {
		due = affordable
	}
	return due * p.perPeriod
}

// PoolOf is an employer's unallocated pool. Zero for an address that has
// never funded one.
func PoolOf(employer address) int64 {
	if e := getEmployer(employer.String()); e != nil {
		return e.pool
	}
	return 0
}

// RosterOf is the number of open positions an employer holds.
func RosterOf(employer address) int {
	if e := getEmployer(employer.String()); e != nil {
		return e.roster
	}
	return 0
}

// BalanceOf is an employee's accrued, unclaimed balance.
func BalanceOf(employee address) int64 { return ledger.BalanceOf(employee.String()) }

// PerPeriodOf is a position's gross salary per period.
func PerPeriodOf(employer, employee address) int64 {
	return mustPosition(employer, employee).perPeriod
}

// PaidPeriodsOf is how many whole periods a position has settled.
func PaidPeriodsOf(employer, employee address) int64 {
	return mustPosition(employer, employee).paidPeriods
}

// EndHeightOf is a position's end height, or OpenEnded.
func EndHeightOf(employer, employee address) int64 {
	return mustPosition(employer, employee).endHeight
}

// HasPosition reports whether a position is open, without panicking on
// absence — every other position accessor panics, which makes them
// unusable as an existence probe.
func HasPosition(employer, employee address) bool {
	return positions.Get(posKey(employer, employee)) != nil
}

// OpenPositions is the number of open positions across every employer.
func OpenPositions() int { return positions.Size() }

// Employers is the number of addresses that have ever funded a pool.
// Note the tense: an employer record survives a pool going to zero, so
// this is not a count of currently-funded employers.
func Employers() int { return employers.Size() }

// TotalPooled is the sum of every employer's unallocated pool.
func TotalPooled() int64 {
	var sum int64
	employers.Iterate("", "", func(_ string, v any) bool {
		sum += v.(*employer).pool
		return false
	})
	return sum
}

// AccruedTotal is the sum of every employee's unclaimed balance.
func AccruedTotal() int64 { return ledger.UsersTotal() }

// FeesAccrued is the fee pot awaiting WithdrawFees.
func FeesAccrued() int64 { return ledger.FeesAccrued() }

// Liabilities is every coin this realm owes to anyone: pooled coins plus
// the ledger's own total (employee balances plus the fee pot).
func Liabilities() int64 {
	total, ok := checkedAdd(TotalPooled(), ledger.Liabilities())
	if !ok {
		panic("liabilities would overflow")
	}
	return total
}

// Held is the realm's actual ugnot balance, read from the chain.
func Held() int64 { return coinio.HeldAt(self, Denom) }

// Surplus is coins held beyond every obligation — what SweepSurplus
// would move. It is zero when every coin arrived through an entrypoint.
func Surplus() int64 {
	h, l := Held(), Liabilities()
	if h <= l {
		return 0
	}
	return h - l
}

// Address is this realm's own address.
func Address() address { return self }

// Height is the current chain height, exposed so a caller can compute
// period boundaries against the same clock this realm uses.
func Height() int64 { return runtime.ChainHeight() }

// --- internals ---

func posKey(employer, employee address) string {
	return employer.String() + "|" + employee.String()
}

func getEmployer(key string) *employer {
	v := employers.Get(key)
	if v == nil {
		return nil
	}
	return v.(*employer)
}

func mustEmployer(key string) *employer {
	e := getEmployer(key)
	if e == nil {
		panic("unknown employer")
	}
	return e
}

func mustPosition(employer, employee address) *position {
	v := positions.Get(posKey(employer, employee))
	if v == nil {
		panic("unknown position")
	}
	return v.(*position)
}

func checkedAdd(a, b int64) (int64, bool) {
	c := a + b
	if (b > 0 && c < a) || (b < 0 && c > a) {
		return 0, false
	}
	return c, true
}

// checkedMul reports a*b and whether it is exact. Both operands here are
// non-negative (duePeriods never returns a negative, perPeriod is validated
// at or above MinPerPeriod), so the division test is sufficient and the
// sign cases a general version would need are deliberately absent.
func checkedMul(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	c := a * b
	if c/b != a {
		return 0, false
	}
	return c, true
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// --- render ---

func Render(path string) string {
	var b strings.Builder
	b.WriteString("# payroll\n\n")
	b.WriteString("Employer-funded recurring salary disbursement. ")
	b.WriteString("An allowance refills; a salary accrues.\n\n")

	if path == "" {
		b.WriteString("## Totals\n\n")
		b.WriteString("| field | value |\n|---|---|\n")
		b.WriteString("| employers | " + itoa(int64(Employers())) + " |\n")
		b.WriteString("| open positions | " + itoa(int64(OpenPositions())) + " |\n")
		b.WriteString("| pooled | " + itoa(TotalPooled()) + " " + Denom + " |\n")
		b.WriteString("| accrued to employees | " + itoa(AccruedTotal()) + " " + Denom + " |\n")
		b.WriteString("| fees accrued | " + itoa(FeesAccrued()) + " " + Denom + " |\n")
		b.WriteString("| held | " + itoa(Held()) + " " + Denom + " |\n")
		b.WriteString("| surplus | " + itoa(Surplus()) + " " + Denom + " |\n\n")
		b.WriteString("Salary is paid in arrears: a period must complete ")
		b.WriteString("before it is owed. Accrue is permissionless.\n\n")
		b.WriteString("Append an employer address to this path to see ")
		b.WriteString("their roster.\n")
		return b.String()
	}

	who := sanitize.InlineText(path)
	b.WriteString("## Roster of " + who + "\n\n")
	e := getEmployer(path)
	if e == nil {
		b.WriteString("No employer record at that address.\n")
		return b.String()
	}
	b.WriteString("Pool: " + itoa(e.pool) + " " + Denom + ", ")
	b.WriteString("open positions: " + itoa(int64(e.roster)) + "\n\n")

	now := runtime.ChainHeight()
	b.WriteString("| employee | per period | period | paid | due |\n")
	b.WriteString("|---|---|---|---|---|\n")
	prefix := path + "|"
	positions.Iterate(prefix, prefix+"\xff", func(_ string, v any) bool {
		p := v.(*position)
		b.WriteString("| " + sanitize.InlineText(p.employee.String()))
		b.WriteString(" | " + itoa(p.perPeriod))
		b.WriteString(" | " + itoa(p.periodBlocks))
		b.WriteString(" | " + itoa(p.paidPeriods))
		b.WriteString(" | " + itoa(duePeriods(p, now)) + " |\n")
		return false
	})
	return b.String()
}
